contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address receiver, uint256 amount) public payable {
        // require a sane receiver (non-zero) to avoid immediate revert from depositUsdc input check
        require(receiver != address(0));
        // Ensure this contract has enough USDC allowance/ balance in the environment is out of scope,
        // but we only reason about observable effects when call does not revert.

        // Read pre-state
        uint256 beforeRoundUsdc = c.roundUsdcBalance();
        uint256 beforeReceiverUsdc = c.usdcBalance(receiver);

        // Attempt the deposit and capture whether it reverted
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterRoundUsdc = c.roundUsdcBalance();
        uint256 afterReceiverUsdc = c.usdcBalance(receiver);

        // General rule: if depositUsdc did not revert, then roundUsdcBalance increases by amount
        // and the receiver's usdcBalance increases by amount. If it reverted, no guarantee is required.
        assert(reverted || (afterRoundUsdc == beforeRoundUsdc + amount && afterReceiverUsdc == beforeReceiverUsdc + amount));
    }

    receive() external payable {}
}

