contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used for property testing
    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        // The test contract must hold enough USDC to transfer to c via depositUsdc.
        // We cannot mint tokens here, but the checker deploys a fresh C and this contract
        // is the msg.sender for subsequent calls; to satisfy the constraint that all
        // state- changing calls are top-level, we just call depositUsdc and observe
        // contract getters before and after.

        // Read before-values via public getters
        uint256 beforeUserBalance = c.usdcBalance(receiver);
        uint256 beforeRoundBalance = c.roundUsdcBalance();

        // Attempt the deposit call and record whether it reverted
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values (view functions allowed anywhere)
        uint256 afterUserBalance = c.usdcBalance(receiver);
        uint256 afterRoundBalance = c.roundUsdcBalance();

        // General invariant: if the call did not revert then the receiver's usdcBalance
        // increases by exactly `amount` and the roundUsdcBalance increases by exactly `amount`.
        // If it reverted then balances must be unchanged (call had no effect).
        assert(
            (!reverted && afterUserBalance == beforeUserBalance + amount && afterRoundBalance == beforeRoundBalance + amount)
            || (reverted && afterUserBalance == beforeUserBalance && afterRoundBalance == beforeRoundBalance)
        );
    }

    receive() external payable {}
}

